import { Heading, Text, Tag } from "@hulianui/ui";
import { StatsBlock } from "../../blocks/_blocks/stats";
import { MilestoneTimelineBlock } from "../../blocks/_blocks/milestone-timeline";
import { TeamGridBlock } from "../../blocks/_blocks/team-grid";
import { TestimonialsBlock } from "../../blocks/_blocks/testimonials";
import { CtaBlock } from "../../blocks/_blocks/cta";
export function AboutPage() {
    return (<div className="bg-bg">
      <section className="px-6 pt-20 pb-6 text-center">
        <div className="mx-auto max-w-3xl flex flex-col items-center gap-3">
          <Tag variant="soft" tone="brand" size="sm">About Hanyun</Tag>
          <Heading level={1} size="4xl" weight="bold" balance>Make every piece of data more valuable</Heading>
          <Text tone="muted" size="lg">We believe that good tools should disappear into the work.</Text>
        </div>
      </section>
      <section className="px-6 py-12">
        <div className="mx-auto max-w-3xl flex flex-col gap-4 text-center">
          <Heading level={2} size="2xl" weight="bold">our story</Heading>
          <Text tone="muted" size="lg">Hanyun was born out of a simple obsession: the team was slowed down by fragmented systems, duplicate forms, and late data. We were tired of carrying information back and forth between tools, so we decided to build a platform that could connect them together.</Text>
          <Text tone="muted" size="lg">From the first line of code, we have written "restraint" into our genes - we don't pile up functions and only solve real problems. Today, Hanyun provides thousands of teams with a one-stop base from data access to intelligent decision-making, and our obsession with simplicity and reliability has never changed.</Text>
          <Text tone="muted" size="lg">This is not the end. We are still working hard on "making complexity disappear".</Text>
        </div>
      </section>
      <StatsBlock />
      <MilestoneTimelineBlock />
      <TeamGridBlock />
      <TestimonialsBlock />
      <CtaBlock />
    </div>);
}

